questionvariables.text:
n:rand(3)+1;
coeff_r2:rand(3)+2;
eqn_1:coeff_r2*x;

eqn_2:n*x^2;


/* JSXGraph*/
f_1:n*x^2;
f_2:coeff_r2*x;
/*Compute the intersection points (x1,y1) and (x2,y2)*/
/*We use the solve function here, but this isn't always guaranteed to work*/
solns: solve(f_1=f_2, x);
x_1:rhs(solns[1]);
x_2:rhs(solns[2]);
y_1:ev(f_1,x=x_1);
y_2:ev(f_1,x=x_2);

/*Boundaries of the display box*/
min_x:if x_1<x_2 then x_1 -1 else x_2 -1;
max_x:if x_1<x_2 then x_2 +1 else x_1 +1;
min_y:if y_1<y_2 then y_1 -5 else y_2 -5;
max_y:if y_1<y_2 then y_2 +5 else y_1 +5;

/*Values of a and b*/
a: if x_1<x_2 then x_1 else x_2
b: if x_1<x_2 then x_2 else x_1;

eqn_11:int(eqn_1^2,x);
eqn_22:int(eqn_2^2,x);
eqn_11_1:subst(b,x,eqn_11);
eqn_22_1:subst(b,x,eqn_22);
eqn_11_2:subst(a,x,eqn_11);
eqn_22_2:subst(a,x,eqn_22);
ta:(eqn_11_1-eqn_22_1)*pi;
